import 'package:nai_huishi/core/constants/prompt_capsule_data.dart';

PromptCapsuleSubgroup _sg(String name, String packed) {
  final tags = <PromptCapsuleTag>[];
  for (final raw in packed.split('|')) {
    final piece = raw.trim();
    if (piece.isEmpty) continue;
    final i = piece.indexOf('=');
    final en = (i == -1 ? piece : piece.substring(0, i)).trim();
    final zh_ = (i == -1 ? piece : piece.substring(i + 1)).trim();
    if (en.isNotEmpty)
      tags.add(PromptCapsuleTag(en: en, zh: zh_.isEmpty ? en : zh_));
  }
  return PromptCapsuleSubgroup(name: name, tags: tags);
}

PromptCapsuleCategory _cat(
        String name, List<PromptCapsuleSubgroup> subgroups) =>
    PromptCapsuleCategory(name: name, subgroups: subgroups);

