/// 合并三批词库，按分类+子类名去重（同分类内重复的 en tag 只保留首次出现）
List<PromptCapsuleCategory> buildMergedCapsules() {
  final sources = [_capsule1, _capsule2, _capsule3];
  final out = <PromptCapsuleCategory>[];
  final seenByCat = <String, Set<String>>{};
  for (final src in sources) {
    for (final ec in src) {
      PromptCapsuleCategory? target;
      for (final c in out) {
        if (c.name == ec.name) {
          target = c;
          break;
        }
      }
      if (target == null) {
        target = PromptCapsuleCategory(name: ec.name, subgroups: []);
        out.add(target);
        seenByCat[ec.name] = {};
      }
      final seen = seenByCat[ec.name]!;
      for (final es in ec.subgroups) {
        PromptCapsuleSubgroup? subgroup;
        for (final s in target.subgroups) {
          if (s.name == es.name) {
            subgroup = s;
            break;
          }
        }
        if (subgroup == null) {
          subgroup = PromptCapsuleSubgroup(name: es.name, tags: []);
          target.subgroups.add(subgroup);
        }
        for (final t in es.tags) {
          if (seen.contains(t.en)) continue;
          seen.add(t.en);
          subgroup.tags.add(t);
        }
      }
    }
  }
  return out;
}

/// 最终合并结果，懒加载缓存
List<PromptCapsuleCategory>? _cachedMerged;
List<PromptCapsuleCategory> get mergedPromptCapsules {
  _cachedMerged ??= buildMergedCapsules();
  return _cachedMerged!;
}
